export class LoginModel {
  #subs = new Set();
  constructor() { this.email = ""; this.busy = false; }
  get submitEnabled() { return this.email !== "" && !this.busy; }  // decision
  async submit() { this.busy = true; this.#emit(); /* command */ }
  subscribe(fn) { this.#subs.add(fn); return () => this.#subs.delete(fn); }
  #emit() { for (const fn of this.#subs) fn(); }
}
